sales.generated_sql:
SELECT "Mail ID"
FROM Sales
WHERE "Payment mode" = 'CASH';

SELECT 'Total Revenue' AS total_revenue
FROM Sales
WHERE "Payment mode" = 'Card';

SELECT "Customer ID"
FROM Sales
WHERE "Discount Applied" = 1;

SELECT "Category", AVG("Revenue") AS AvgRevenue
FROM Sales
GROUP BY "Category";

SELECT SUM("Discount Amount") AS TotalDiscount
FROM Sales
WHERE "Month" = 'October';

SELECT "Customer ID"
FROM Sales
WHERE "Product bought" = 'Sneakers';

SELECT SUM("Revenue") AS TotalRevenue
FROM Sales
WHERE "Year" = 2024;

